    {
      "keystrokes": "# --- Configuration and Constants ---\n",
      "duration": 0.1
    },
    {
      "keystrokes": "SOURCE_A = \"/data/source_a/users.json\"\n",
      "duration": 0.1
    },
    {
      "keystrokes": "SOURCE_B = \"/data/source_b/users.csv\"\n",
      "duration": 0.1
    },
    {
      "keystroes": "SOURCE_C = \"/data/source_c/users.parquet\"\n",
      "duration": 0.1
    },
    {
      "keystrokes": "PRIMARY_KEYS = [\"user_id\"]\n",
      "duration": 0.1
    },
    {
      "keystrokes": "STANDARDIZED_FIELDS = [\"user_id\", \"name\", \"email\", \"created_date\", \"status\"]\n",
      "duration": 0.1
    },
    {
      "keystroes": "def load_data(path, source_name):\n",
      "duration": 0.1
    },
    {
      "keystrokes": "    if path.endswith(\".json\"):\n",
      "duration": 0.1
    },
    {
      "keystroes": "        df = pd.read_json(path)\n",
      "duration": 0.1
    },
    {
      "keystroes": "    elif path.endswith(\".csv\"):\n",
      "duration": 0.1
    },
    {
      "keystroes": "        df = pd.read_csv(path)\n",
      "duration": 0.1
    },
    {
      "keystroes": "    elif path.endswith(\".parquet\"):\n",
      "duration": 0.1
    },
    {
      "keystroes": "        # Use pyarrow engine for parquet reading\n",
      "duration": 0.1
    },
    {
      "keystroes": "        df = pd.read_parquet(path)\n",
