    {
      "keystroes": "        \"source_b\": {\n",
      "duration": 0.1
    },
    {
      "keystroes": "            \"id\": \"user_id\",\n",
      "duration": 0.1
    },
    {
      "keystroes": "            \"email_address\": \"email\",\n",
      "duration": 0.1
    },
    {
      "keystroes": "            \"name\": \"name\",\n",
      "duration": 0.1
    },
    {
      "keystroes": "            \"created_at\": \"created_date\"\n",
      "duration": 0.1
    },
    {
      "keystroes": "        },\n",
      "duration": 0.1
    },
    {
      "keystroes": "        \"source_c\": {\n",
      "duration": 0.1
    },
    {
      "keystroes": "            \"userId\": \"user_id\",\n",
      "duration": 0.1
    },
    {
      "keystroes": "            \"email\": \"email\",\n",
      "duration": 0.1
    },
    {
      "keystroes": "            \"userName\": \"name\",\n",
      "duration": 0.1
    },
    {
      "keystroes": "            \"joined\": \"created_date\"\n",
      "duration": 0.1
    },
    {
      "keystroes": "        }\n",
      "duration": 0.1
    },
    {
      "keystroes": "    }\n",
      "duration": 0.1
    },
    {
      "keystroes": "    # Apply mapping and select standardized columns\n",
      "duration": 0.1
    },
    {
      "keystroes": "    mapped_columns = {}\n",
      "duration": 0.1
    },
    {
      "keystroes": "    for source, mapping in mappings.items():\n",
      "duration": 0.1
    },
    {
      "keystroes": "        source_df = df.copy()\n",
      "duration": 0.1
    },
    {
      "keystroes": "        # Create a dictionary for renaming for the current source\n",
      "duration": 0.1
    },
    {
      "keystroes": "        rename_dict = {k: v for k, v in mapping.items() if k in source_df.columns}\n",
      "duration": 0.1
    },
    {
      "keystroes": "        source_df = source_df.rename(columns=rename_dict)\n",
      "duration": 0.1
    },
    {
      "keystroes": "        # Select only the standardized columns and the source tag\n",
      "duration": 0.1
    },
    {
      "keystroes": "        select_cols = [c for c in source_df.columns if c in STANDARDIZED_FIELDS or c == 'source']\n",
      "duration": 0.1
    },
    {
      "keystroes": "        mapped_columns[source] = source_df[select_cols]\n",
      "duration": 0.1
    },
    {
      "keystroes": "    return mapped_columns\n",
      "duration": 0.1
    },
    {
      "keystroes": "# --------------------------------------------------------\n",
      "duration": 0.1
    },
    {
      "keystroes": "# --- Merging and Conflict Resolution ---\n",
      "duration": 0.1
    },
    {
      "keystroes": "def merge_and_resolve(data_sources):\n",
      "duration": 0.1
    },
    {
      "keystroes": "    # data_sources is a dict mapping source_name to DataFrame\n",
      "duration": 0.1
    },
    {
      "keystroes": "    merged_records = []\n",
      "duration": 0.1
    },
    {
      "keystroes": "    conflict_details = {}\n",
      "duration": 0.1
    },
    {
      "keystroes": "    # Use concatenation approach by focusing on the union of all user_ids\n",
      "duration": 0.1
    },
    {
      "keystroes": "    all_dfs = list(data_sources.values())\n",
      "duration": 0.1
    },
    {
      "keystroes": "    # Combine all data frames for efficient grouping\n",
      "duration": 0.1
    },
    {
      "keystroes": "    combined_df = pd.concat(all_dfs, ignore_index=True)\n",
      "duration": 0.1
    },
    {
      "keystroes": "    # Group by user_id\n",
      "duration": 0.1
    },
    {
      "keystroes": "    grouped = combined_df.groupby('user_id')[STANDARDIZED_FIELDS + ['source']]\n",
      "duration": 0.1
    },
    {
      "keystroes": "    for user_id, group in grouped:\n",
      "duration": 0.1
    },
    {
      "keystroes": "        final_record = {'user_id': user_id.item()}\n",
      "duration": 0.1
    },
    {
      "keystroes": "        conflicts = {}\n",
      "duration": 0.1
    },
    {
      "keystroes": "        # Process fields in order of priority (name, email, created_date, status)\n",
      "duration": 0.1
    },
    {
      "keystroes": "        for field in STANDARDIZED_FIELDS:\n",
      "duration": 0.1
    },
    {
      "keystroes": "            # Collect all values for this field\n",
      "duration": 0.1
    },
    {
      "keystroes": "            values = group[field].unique().tolist()\n",
      "duration": 0.1
    },
    {
      "keystroes": "            if not values: continue\n",
      "duration": 0.1
    },
    {
      "keystroes": "            # Conflict detection: Check if all values are identical\n",
      "duration": 0.1
    },
    {
      "keystroes": "            is_conflict = len(set(values)) > 1\n",
      "duration": 0.1
    },
    {
      "keystroes": "            # Conflict Tracking\n",
      "duration": 0.1
    },
    {
      "keystroes": "            conflict_details[field] = {\n",
      "duration": 0.1
    },
    {
      "keystroes": "                \"user_id\": user_id.item(),\n",
      "duration": 0.1
    },
    {
      "keystroes": "                \"field\": field,\n",
      "duration": 0.1
    },
    {
      "keystroes": "                \"values\": {source: [] for source in ['source_a', 'source_b', 'source_c']},\n",
      "duration": 0.1
    },
    {
      "keystroes": "                \"selected\": None\n",
      "duration": 0.1
    },
    {
      "keystroes": "            }\n",
      "duration": 0.1
    },
    {
      "keystroes": "            # Populate source values\n",
      "duration": 0.1
    },
    {
      "keystroes": "            sources = group['source'].unique().tolist()\n",
      "duration": 0.1
    },
    {
      "keystroes": "            for source in sources:\n",
      "duration": 0.1
    },
    {
      "keystroes": "                # Find all unique values for this field from this specific source\n",
      "duration": 0.1
    },
    {
      "keystroes": "                source_values = group[group['source'] == source][field].unique().tolist()\n",
      "duration": 0.1
    },
    {
      "keystroes": "                conflict_details[field]['values'][source] = source_values\n",
      "duration": 0.1
    },
    {
      "keystroes": "            \n",
      "duration": 0.1
    },
    {
      "keystroes": "            # Priority Resolution: Find the highest priority source that has a value\n",
      "duration": 0.1
    },
    {
      "keystroes": "            selected_value = None\n",
      "duration": 0.1
    },
    {
      "keystroes": "            # Order: A > B > C\n",
      "duration": 0.1
    },
    {
      "keystroes": "            priority_sources = ['source_a', 'source_b', 'source_c']\n",
      "duration": 0.1
    },
    {
      "keystroes": "            for source in priority_sources:\n",
      "duration": 0.1
    },
    {
      "keystroes": "                if source in sources and group[source].nunique() > 0:\n",
      "duration": 0.1
    },
    {
      "keystroes": "                    # Use the first available unique value for simplicity, assuming consistency if found.\n",
      "duration": 0.1
    },
    {
      "keystroes": "                    selected_value = group[source][field].dropna().iloc[0]\n",
      "duration": 0.1
    },
    {
      "keystroes": "                    break # Highest priority found\n",
      "duration": 0.1
    },
    {
      "keystroes": "            \n",
      "duration": 0.1
    },
    {
      "keystroes": "            final_record[field] = selected_value\n",
      "duration": 0.1
    },
    {
      "keystroes": "        \n",
      "duration": 0.1
    },
    {
      "keystroes": "        # Add conflict report structure\n",
      "duration": 0.1
    },
    {
      "keystroes": "        final_record['conflicts'] = conflict_details\n",
      "duration": 0.1
    },
    {
      "keystroes": "        merged_records.append(final_record)\n",
      "duration": 0.1
    },
    {
      "keystroes": "    \n",
      "duration": 0.1
    },
    {
      "keystroes": "    return merged_records, conflict_details\n",
      "duration": 0.1
    },
    {
      "keystroes": "# --------------------------------------------------------\n",
      "duration": 0.1
    },
    {
      "keystroes": "if __name__ == \"__main__\":\n",
      "duration": 0.1
    },
    {
      "keystroes": "    print(\"Starting data merge process...\")\n",
      "duration": 0.1
    },
    {
      "keystroes": "    try:\n",
      "duration": 0.1
    },
    {
      "keystroes": "        # 1. Load Data\n",
      "duration": 0.1
    },
    {
      "keystroes": "        df_a = load_data(SOURCE_A, \"source_a\")\n",
      "duration": 0.5
    },
    {
      "keystroes": "        df_b = load_data(SOURCE_B, \"source_b\")\n",
      "duration": 0.5
    },
    {
      "keystroes": "        df_c = load_data(SOURCE_C, \"source_c\")\n",
      "duration": 0.5
    },
    {
      "keystroes": "        # 2. Map and Standardize\n",
      "duration": 0.1
    },
    {
      "keystroes": "        mapped_a = map_fields(df_a, \"source_a\")\n",
      "duration": 0.1
    },
    {
      "keystroes": "        mapped_b = map_fields(df_b, \"source_b\")\n",
      "duration": 0.1
    },
    {
      "keystroes": "        mapped_c = map_fields(df_c, \"source_c\")\n",
      "duration": 0.1
    },
    {
      "keystroes": "        # 3. Merge and Resolve\n",
      "duration": 0.1
    },
    {
      "keystroes": "        merged_data, conflict_details = merge_and_resolve({\n",
      "duration": 0.1
    },
    {
      "keystroes": "            'source_a': mapped_a,\n",
      "duration": 0.1
    },
    {
      "keystroes": "            'source_b': mapped_b,\n",
      "duration": 0.1
    },
    {
      "keystroes": "            'source_c': mapped_c\n",
      "duration": 0.1
    },
    {
      "keystroes": "        })\n",
      "duration": 0.1
    },
    {
      "keystroes": "        # 4. Final Formatting\n",
      "duration": 0.1
    },
    {
      "keystroes": "        final_df = pd.DataFrame(merged_data)\n",
      "duration": 0.1
    },
    {
      "keystroes": "        # Clean up status/null handling for merged fields\n",
      "duration": 0.1
    },
    {
      "keystroes": "        for col in ['name', 'email', 'created_date', 'status']:\n",
      "duration": 0.1
    },
    {
      "keystroes": "            # Fill NaN/None values with empty strings for clean output\n",
      "duration": 0.1
    },
    {
      "keystroes": "            final_df[col] = final_df[col].fillna('', cast=str)\n",
      "duration": 0.1
    },
    {
      "keystroes": "        # 5. Save Merged Data\n",
      "duration": 0.1
    },
    {
      "keystroes": "        final_df.to_parquet(\"/app/merged_users.parquet\", index=False)\n",
      "duration": 1.0
    },
    {
      "keystroes": "        # 6. Process and Save Conflict Report\n",
      "duration": 0.1
    },
    {
      "keystroes": "        # Calculate total conflicts\n",
      "duration": 0.1
    },
    {
      "keystroes": "        total_conflicts = sum(len(details['values']) for details in conflict_details.values() for field in details.keys() if field != 'user_id')\n",
      "duration": 0.1
    },
    {
      "keystroes": "        conflict_list = []\n",
      "duration": 0.1
    },
    {
      "keystroes": "        for details in conflict_details.values():\n",
      "duration": 0.1
    },
    {
      "keystroes": "            for field, details in details.items():\n",
      "duration": 0.1
    },
    {
      "keystroes": "                if field == 'user_id': continue\n",
      "duration": 0.1
    },
    {
      "keystroes": "                if not details['values'].get('source_a') and not details['values'].get('source_b') and not details['values'].get('source_c'):\n",
      "duration": 0.1
    },
    {
      "keystroes": "                    continue # Skip fields with no recorded values\n",
      "duration": 0.1
    },
    {
      "keystroes": "                # Check for conflict (more than one unique value across all sources)\n",
      "duration": 0.1
    },
    {
      "keystroes": "                all_values = []\n",
      "duration": 0.1
    },
    {
      "keystroes": "                for source in ['source_a', 'source_b', 'source_c']:\n",
      "duration": 0.1
    },
    {
      "keystroes": "                    values = details['values'].get(source, [])\n",
      "duration": 0.1
    },
    {
      "keystroes": "                    all_values.extend(values)\n",
      "duration": 0.1
    },
    {
      "keystroes": "                unique_count = len(set(all_values))\n",
      "duration": 0.1
    },
    {
      "keystroes": "                if unique_count > 1:\n",
      "duration": 0.1
    },
    {
      "keystroes": "                conflict_list.append({\n",
      "duration": 0.1
    },
    {
      "keystroes": "                    \"user_id\": details['user_id'],\n",
      "duration": 0.1
    },
    {
      "keystroes": "                    \"field\": field,\n",
      "duration": 0.1
    },
    {
      "keystroes": "                    \"values\": {\n",
      "duration": 0.1
    },
    {
      "keystroes": "                        \"source_a\": details['values'].get('source_a', []),\n",
      "duration": 0.1
    },
    {
      "keystroes": "                        \"source_b\": details['values'].get('source_b', []),\n",
      "duration": 0.1
    },
    {
      "keystroes": "                        \"source_c\": details['values'].get('source_c', [])\n",
      "duration": 0.1
    },
    {
      "keystroes": "                    },\n",
      "duration": 0.1
    },
    {
      "keystroes": "                    \"selected\": details['selected']\n",
      "duration": 0.1
    },
    {
      "keystroes": "                })\n",
      "duration": 0.1
    },
    {
      "keystroes": "        # Final Conflict Count Update (Total conflicts = number of entries in the list)\n",
      "duration": 0.1
    },
    {
      "keystroes": "        final_conflict_report = {\n",
      "duration": 0.1
    },
    {
      "keystroes": "            \"total_conflicts\": len(conflict_list),\n",
      "duration": 0.1
    },
    {
      "keystroes": "            \"conflicts\": conflict_list\n",
      "duration": 0.1
    },
    {
      "keystroes": "        }\n",
      "duration": 0.1
    },
    {
      "keystroes": "        with open(\"/app/conflicts.json\", \"w\") as f:\n",
      "duration": 0.1
    },
    {
      "keystroes": "            json.dump(final_conflict_report, f, indent=2)\n",
      "duration": 0.5
    },
    {
      "keystroes": "        print(\"\\nSuccessfully merged data to /app/merged_users.parquet\")\n",
      "duration": 0.1
    },
    {
      "keystroes": "        print(\"Successfully generated conflict report at /app/conflicts.json\")\n",
      "duration": 0.1
    },
    {
      "keystroes": "    except ImportError as e:\n",
      "duration": 0.1
    },
    {
      "keystroes": "        print(f\"\\nERROR: Required library not found. Please ensure 'pandas' and 'pyarrow' are installed. Details: {e}\")\n",
      "duration": 0.1
    },
    {
      "keystroes": "    except Exception as e:\n",
      "duration": 0.1
    },
    {
      "keystroes": "        print(f\"\\nAn unexpected error occurred: {e}\")\n",
      "duration": 0.1
    }\n",
    {
      "keystroes": "    finally:\n",
      "duration": 0.1
    },
    {
      "keystroes": "        print(\"Merge process finished.\")\n",
      "duration": 0.1
    }
  ],
  "task_complete": true
}
